import React, { useState, useEffect } from "react";
import { database } from "../firebase";
import { dbRef, onValueRef, updateData, setData } from "../firebaseHelpers";

const HabitTracker = ({ user }) => {
  const [habits, setHabits] = useState(["Workout", "Read", "Relax"]);
  const [history, setHistory] = useState({});
  const [isEditing, setIsEditing] = useState(false);
  const [showHeatmap, setShowHeatmap] = useState(false);

  const [tempHabits, setTempHabits] = useState([]);

  const today = new Date();
  const currentDayIndex = today.getDay() === 0 ? 6 : today.getDay() - 1;

  const getWeekDates = () => {
    const curr = new Date();
    const first = curr.getDate() - curr.getDay() + 1;
    const dates = [];
    for (let i = 0; i < 7; i++) {
      const day = new Date(curr.setDate(first + i));
      dates.push(day.toISOString().split("T")[0]);
    }
    return dates;
  };

  const weekDates = getWeekDates();
  const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

  useEffect(() => {
    if (!user) return;

    const habitsRef = dbRef(`users/${user.uid}/habitData`);

    const unsubscribe = onValueRef(habitsRef, (snapshot) => {
      const data =
        snapshot && snapshot.val
          ? snapshot.val()
          : (snapshot || {}).val && snapshot.val();
      if (data) {
        if (data.list) setHabits(data.list);
        if (data.history) setHistory(data.history);
      }
    });

    return () => {
      if (typeof unsubscribe === "function") {
        unsubscribe();
      }
    };
  }, [user]);

  const toggleHabit = (habitIndex, dateStr) => {
    if (!user || isEditing) return;

    const safeHabitIndex = Number(habitIndex);
    if (!Number.isInteger(safeHabitIndex) || safeHabitIndex < 0) return;

    if (typeof dateStr !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return;

    const newHistory = { ...history };
    if (!Object.prototype.hasOwnProperty.call(newHistory, safeHabitIndex)) {
      newHistory[safeHabitIndex] = {};
    }

    if (Object.prototype.hasOwnProperty.call(newHistory[safeHabitIndex], dateStr) && newHistory[safeHabitIndex][dateStr]) {
      delete newHistory[safeHabitIndex][dateStr];
    } else {
      newHistory[safeHabitIndex][dateStr] = true;
    }

    setHistory(newHistory);
    updateData(dbRef(`users/${user.uid}/habitData`), {
      history: newHistory,
    });
  };

  const startEditing = () => {
    setTempHabits([...habits]);
    setIsEditing(true);
    setShowHeatmap(false);
  };

  const handleHabitNameChange = (index, value) => {
    const newTemp = [...tempHabits];
    newTemp[index] = value;
    setTempHabits(newTemp);
  };

  const deleteHabit = (index) => {
    const newTemp = tempHabits.filter((_, i) => i !== index);
    setTempHabits(newTemp);
  };

  const addNewHabitRow = () => {
    setTempHabits([...tempHabits, ""]);
  };

  const saveChanges = () => {
    const cleanHabits = tempHabits.filter((h) => h.trim() !== "");
    setHabits(cleanHabits);
    setIsEditing(false);

    if (user) {
      const ref = dbRef(`users/${user.uid}/habitData`);
      setData(ref, {
        list: cleanHabits,
      });
      if (database && typeof database.set === "function") {
        try {
          database.set(ref, { list: cleanHabits });
        } catch (e) {}
      }
    }
  };

  const cancelChanges = () => {
    setIsEditing(false);
    setTempHabits([]);
  };

  const generateYearDays = () => {
    const dates = [];
    const year = new Date().getFullYear();
    const d = new Date(year, 0, 1);

    while (d.getFullYear() === year) {
      dates.push(d.toISOString().split("T")[0]);
      d.setDate(d.getDate() + 1);
    }
    return dates;
  };
  const yearDays = generateYearDays();

  const displayHabits = isEditing ? tempHabits : habits;

  return (
    <div className="bg-card shadow rounded-lg p-6 max-w-4xl mx-auto relative transition-colors duration-200">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-semibold text-foreground">
          Habit Tracker
        </h2>
        <div className="flex gap-2">
          {!isEditing && (
            <>
              <button
                onClick={() => setShowHeatmap(!showHeatmap)}
                className={`p-2 rounded-full transition-colors ${
                  showHeatmap
                    ? "bg-primary/15 text-primary"
                    : "text-muted-foreground hover:bg-muted/60 hover:text-foreground"
                }`}
                title="Yearly View"
                aria-label="Toggle yearly view"
              >
                <svg
                  className="w-5 h-5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"
                  />
                </svg>
              </button>
              <button
                onClick={startEditing}
                className="text-muted-foreground hover:text-foreground p-2 rounded-full hover:bg-muted/60 transition-colors"
                title="Edit Habits"
                aria-label="Edit habits"
              >
                <svg
                  className="w-5 h-5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"
                  />
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"
                  />
                </svg>
              </button>
            </>
          )}
        </div>
      </div>

      <div className="grid grid-cols-[1.5fr_repeat(7,_1fr)] gap-2 mb-4">
        <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wider self-end pb-1 pl-2">
          {isEditing ? "Editing Mode" : "Habit"}
        </div>
        {days.map((day, i) => (
          <div
            key={day}
            className="flex flex-col items-center gap-1 h-8 justify-end"
          >
            {i === currentDayIndex && (
              <div className="w-1.5 h-1.5 rounded-full bg-muted-foreground mb-0.5"></div>
            )}
            <div
              className={`text-sm font-medium ${
                i === currentDayIndex
                  ? "text-foreground"
                  : "text-muted-foreground"
              }`}
            >
              {day}
            </div>
          </div>
        ))}
      </div>

      <div className="space-y-1">
        {displayHabits.map((habit, hIndex) => (
          <div
            key={hIndex}
            className="grid grid-cols-[1.5fr_repeat(7,_1fr)] gap-2 items-center p-2 rounded-lg"
          >
            <div className="pr-2">
              {isEditing ? (
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => deleteHabit(hIndex)}
                    className="text-muted-foreground/50 hover:text-red-500 dark:hover:text-red-400 transition-colors"
                    aria-label={`Delete ${habit} habit`}
                  >
                    <svg
                      className="w-4 h-4"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M6 18L18 6M6 6l12 12"
                      />
                    </svg>
                  </button>
                  <input
                    type="text"
                    value={habit}
                    onChange={(e) =>
                      handleHabitNameChange(hIndex, e.target.value)
                    }
                    className="w-full text-sm border-b border-border focus:border-primary outline-none py-1 bg-transparent text-foreground"
                    placeholder="Habit name..."
                    autoFocus={isEditing && habit === ""}
                    aria-label={`Habit name for ${habit}`}
                  />
                </div>
              ) : (
                <div className="font-medium text-foreground truncate pl-2">
                  {habit}
                </div>
              )}
            </div>

            {weekDates.map((dateStr, dIndex) => {
              const isChecked = (Object.prototype.hasOwnProperty.call(history, hIndex) &&
                Object.prototype.hasOwnProperty.call(history[hIndex] || {}, dateStr))
                ? history[hIndex][dateStr]
                : false;

              return (
                <div key={dateStr} className="flex justify-center">
                  <button
                    onClick={() => toggleHabit(hIndex, dateStr)}
                    disabled={isEditing}
                    className={`
                                w-8 h-8 rounded-md flex items-center justify-center transition-all duration-200
                                ${
                                  isChecked
                                    ? "bg-primary text-primary-foreground"
                                    : "bg-muted text-transparent hover:bg-muted"
                                }
                                ${
                                  isEditing
                                    ? "opacity-30 cursor-not-allowed"
                                    : ""
                                }
                            `}
                    aria-label={`${
                      isChecked ? "Uncheck" : "Check"
                    } ${habit} for ${dateStr}`}
                  >
                    <svg
                      className="w-5 h-5"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={3}
                        d="M5 13l4 4L19 7"
                      />
                    </svg>
                  </button>
                </div>
              );
            })}
          </div>
        ))}

        {isEditing && (
          <div className="pt-4 border-t border-border mt-4">
            <button
              onClick={addNewHabitRow}
              className="text-sm text-primary font-medium hover:text-primary/80 flex items-center gap-1 mb-4 pl-2"
            >
              + Add Habit
            </button>

            <div className="flex gap-3">
              <button
                onClick={saveChanges}
                className="bg-primary text-primary-foreground px-6 py-2 rounded-md hover:bg-primary/85 font-medium text-sm transition-colors"
              >
                Save
              </button>
              <button
                onClick={cancelChanges}
                className="bg-muted text-foreground px-6 py-2 rounded-md hover:bg-muted font-medium text-sm transition-colors"
              >
                Cancel
              </button>
            </div>
          </div>
        )}

        {!isEditing && habits.length === 0 && (
          <div className="text-center py-8 text-muted-foreground text-sm">
            No habits yet. Click the cog to add some!
          </div>
        )}
      </div>

      {showHeatmap && (
        <div className="absolute inset-0 bg-card z-20 flex flex-col p-6 rounded-lg overflow-hidden">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-bold text-foreground">
              Yearly Progress
            </h3>
            <button
              onClick={() => setShowHeatmap(false)}
              className="text-muted-foreground hover:text-foreground"
              aria-label="Close yearly progress view"
            >
              <svg
                className="w-6 h-6"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            </button>
          </div>
          <div className="flex-1 overflow-y-auto space-y-6 pr-2">
            {habits.map((habit, hIndex) => (
              <div key={hIndex}>
                <div className="text-sm font-semibold text-foreground mb-2">
                  {habit}
                </div>
                <div className="flex flex-wrap gap-1">
                    {yearDays.map((dateStr) => {
                      const hasHistory = Object.prototype.hasOwnProperty.call(history, hIndex) &&
                        Object.prototype.hasOwnProperty.call(history[hIndex] || {}, dateStr) &&
                        history[hIndex][dateStr];
                      return (
                      <div
                        key={dateStr}
                        title={dateStr}
                        className={`w-2.5 h-2.5 rounded-sm ${
                          hasHistory
                            ? "bg-green-500 dark:bg-green-600"
                            : "bg-muted"
                        }`}
                        aria-label={`${habit} on ${dateStr}: ${
                          hasHistory
                            ? "completed"
                            : "not completed"
                        }`}
                      ></div>
                      );
                    })}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default HabitTracker;
